<script setup lang="ts">
import { courseImage } from "@/utils/media"
import { courses, useDemoStore, money } from '@/stores/demo'
const levelLabel = (level: string) => ({ Beginner: 'Pemula', Intermediate: 'Menengah', 'All levels': 'Semua tingkat' })[level] ?? level
const store = useDemoStore(); const route = useRoute()
const mine = computed(() => route.path === '/learn/my-courses')
const search = ref(''); const level = ref<string | null>(null); const category = ref<string | null>(null); const open = ref(false); const page = ref(1)
const draft = reactive({ level: null as string | null, category: null as string | null })
const filtered = computed(() => courses.filter(course => (!mine.value || store.data.enrollments.some(e => e.courseId === course.id)) && (!search.value?.trim() || `${course.title} ${course.instructor}`.toLowerCase().includes(search.value.trim().toLowerCase())) && (!level.value || course.level === level.value) && (!category.value || course.category === category.value)))
const visible = computed(() => filtered.value.slice((page.value - 1) * 6, page.value * 6))
watch([search, level, category, mine], () => { page.value = 1 })
function progress(id: number) { const e = store.data.enrollments.find(e => e.courseId === id); const course = courses.find(c => c.id === id); return e && course ? Math.round(e.completed.length / course.lessons.length * 100) : 0 }
function rating(id: number) { const reviews = store.data.reviews.filter(r => r.courseId === id); return reviews.length ? (reviews.reduce((sum, r) => sum + r.rating, 0) / reviews.length).toFixed(1) : 'Baru' }
function showFilters() { draft.level = level.value; draft.category = category.value; open.value = true }
function reset() { search.value = ''; level.value = null; category.value = null }
</script>
<template>
  <PageHeader :title="mine ? 'Kursus saya' : 'Katalog kursus'" eyebrow="ACADEMY" :description="mine ? 'Lanjutkan pelajaran atau tinjau kembali materi yang sudah selesai.' : 'Temukan kursus yang sesuai, ikuti demo, dan mulai belajar.'"><VBtn :to="mine ? '/learn/courses' : '/learn/my-courses'" variant="outlined">{{ mine ? 'Lihat katalog kursus' : 'Kursus saya' }}</VBtn></PageHeader>
  <VCard class="mb-6"><VCardText class="d-flex align-center flex-wrap gap-3"><VTextField v-model="search" label="Cari kursus atau instruktur" prepend-inner-icon="ri-search-line" clearable class="flex-grow-1" style="min-inline-size: 180px" /><VBtn variant="outlined" prepend-icon="ri-filter-3-line" @click="showFilters">Filter {{ level || category ? `(${Number(!!level) + Number(!!category)})` : '' }}</VBtn><VBtn v-if="level || category || search" variant="text" @click="reset">Hapus pilihan</VBtn></VCardText></VCard>
  <VRow><VCol v-for="course in visible" :key="course.id" cols="12" sm="6" xl="4"><VCard class="h-100"><RouterLink :to="`/learn/courses/${course.id}`" :aria-label="course.title"><ProductArt :icon="course.icon" :image="courseImage(course.id)" :alt="course.title" /></RouterLink><VCardText class="form-stack"><div class="d-flex justify-space-between gap-2"><VChip color="primary" size="small">{{ course.category }}</VChip><span class="text-body-2"><VIcon icon="ri-star-fill" color="warning" size="16" /> {{ rating(course.id) }}</span></div><div><RouterLink :to="`/learn/courses/${course.id}`" class="text-h6">{{ course.title }}</RouterLink><p class="text-body-2 text-medium-emphasis mt-2">{{ course.instructor }} · {{ levelLabel(course.level) }}</p></div><p class="text-body-2">{{ course.lessons.length }} pelajaran · {{ course.lessons.reduce((sum, l) => sum + l.minutes, 0) }} menit</p><template v-if="mine"><div class="d-flex justify-space-between text-caption"><span>Progres belajar</span><span>{{ progress(course.id) }}%</span></div><VProgressLinear :model-value="progress(course.id)" color="primary" rounded height="6" /><VBtn :to="`/learn/courses/${course.id}`" variant="tonal">Lanjut belajar</VBtn></template><div v-else class="d-flex align-center justify-space-between flex-wrap gap-3"><span class="font-weight-medium">{{ money(course.price) }}</span><VBtn :to="`/learn/courses/${course.id}`" variant="tonal" size="small">Lihat detail kursus</VBtn></div></VCardText></VCard></VCol></VRow>
  <VCard v-if="!visible.length" class="text-center pa-10"><VIcon icon="ri-book-open-line" size="40" /><h3 class="text-h6 my-3">{{ mine ? 'Belum ada kursus yang sesuai' : 'Kursus tidak ditemukan' }}</h3><VBtn v-if="search || level || category" variant="tonal" @click="reset">Kosongkan filter</VBtn><VBtn v-else to="/learn/courses">Lihat katalog kursus</VBtn></VCard>
  <VPagination v-if="filtered.length > 6" v-model="page" :length="Math.ceil(filtered.length / 6)" class="mt-5" />
  <VDialog v-model="open" max-width="460" aria-label="Course filters"><VCard title="Filter kursus"><VCardText class="form-stack"><VSelect v-model="draft.category" :items="[...new Set(courses.map(c => c.category))]" label="Kategori" clearable /><VSelect v-model="draft.level" :items="[...new Set(courses.map(c => c.level))]" label="Tingkat kesulitan" clearable /></VCardText><VCardActions class="pa-4"><VBtn @click="draft.level = null; draft.category = null">Hapus pilihan</VBtn><VSpacer /><VBtn @click="open = false">Batal</VBtn><VBtn variant="flat" @click="level = draft.level; category = draft.category; open = false">Terapkan filter</VBtn></VCardActions></VCard></VDialog>
</template>
